"""Check that the auto-generated code blocks match what the generators write.

A hand edit between the ``# Begin auto-generated code`` and ``# End auto-generated code``
markers, or a change to the name sets in ``automethods._main`` without rerunning
``scripts/autogenerate.py``, fails here. ``scripts/autogenerate.py --check`` regenerates
the files in a scratch directory and compares parsed syntax, so it needs no formatter.

The generator writes from those name sets, not from the classes, so a method added to
Matrix, Vector or Scalar does not change its output. ``test_automethods.py`` catches
that case.
"""

import ast
import re
import subprocess
import sys
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[2]
AUTOGEN_SCRIPT = REPO_ROOT / "scripts" / "autogenerate.py"
PACKAGE_LINE = "graphblas package: "


def test_autogenerated_code_is_in_sync():
    if not AUTOGEN_SCRIPT.exists():  # pragma: no cover (source checkout only)
        pytest.skip("scripts/autogenerate.py not present (installed package, not a checkout)")
    result = subprocess.run(
        [sys.executable, str(AUTOGEN_SCRIPT), "--check"],
        capture_output=True,
        text=True,
        check=False,
    )
    report = f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}"
    checked = [
        line[len(PACKAGE_LINE) :].strip()
        for line in result.stdout.splitlines()
        if line.startswith(PACKAGE_LINE)
    ]

    # Assert which package --check checked before its exit code: it must be this
    # checkout, not the installed graphblas, which in a git worktree is another one
    assert checked, f"--check never reported a package, so it failed before starting.\n{report}"
    expected = str(REPO_ROOT / "graphblas")
    assert checked == [expected], f"--check validated {checked}, not {expected}.\n{report}"

    assert result.returncode == 0, (
        "Auto-generated code is out of date. Run `python scripts/autogenerate.py` and "
        f"commit the result.\n{report}"
    )


def test_generators_rewrite_only_the_copies_in_base_dir(tmp_path, monkeypatch):
    # What --check relies on: given base_dir, each generator reads and rewrites the
    # copies there and leaves the package alone, and callblack=False never runs black.
    from graphblas.core import automethods, infixmethods

    def black(*args, **kwargs):  # pragma: no cover (only on failure)
        raise AssertionError(f"black was run: {args}")

    monkeypatch.setattr(subprocess, "check_call", black)
    src_dir = Path(automethods.__file__).parent
    names = ["automethods.py", "infixmethods.py", "scalar.py", "vector.py", "matrix.py", "infix.py"]
    raw = {name: (src_dir / name).read_bytes() for name in names}
    originals = {name: (src_dir / name).read_text() for name in names}
    for name, text in originals.items():
        # Make every generated block in the copy stale
        stale = re.sub(r"(# Begin auto-generated code.*\n)( *)", r"\1\2_STALE_ = 1\n\2", text)
        assert "_STALE_" in stale, name
        (tmp_path / name).write_text(stale)

    try:
        automethods._main(base_dir=tmp_path, callblack=False)
        infixmethods._main(base_dir=tmp_path, callblack=False)
        rewritten = [name for name in names if (src_dir / name).read_bytes() != raw[name]]
    finally:
        # A generator that ignored base_dir rewrote the package's own file; put it back
        for name in names:
            if (src_dir / name).read_bytes() != raw[name]:  # pragma: no cover (only on failure)
                (src_dir / name).write_bytes(raw[name])
    assert not rewritten

    for name, text in originals.items():
        regenerated = (tmp_path / name).read_text()
        assert "_STALE_" not in regenerated, name
        # Without black the layout differs, so compare parsed syntax as --check does
        assert ast.dump(ast.parse(regenerated)) == ast.dump(ast.parse(text)), name
